/** Lookup by expectation_type (for prefilling the editor in edit mode). */
export const EXPECTATION_BY_TYPE: Record<string, ExpectationSpec> = Object.fromEntries(
  EXPECTATION_CATALOG.map((e) => [e.type, e]),
);

/** Expectations grouped by category, in category order — drives the grouped
 *  expectation picker (antd Select optgroups / the dedicated check page). */
export const EXPECTATIONS_BY_CATEGORY: {
  category: ExpectationCategory;
  specs: ExpectationSpec[];
}[] = EXPECTATION_CATEGORIES.map((category) => ({
  category,
  specs: EXPECTATION_CATALOG.filter((e) => e.category === category),
}));

/**
 * Custom SQL (ADR 0019) is offered only on SQL-queryable connections — it runs a literal SQL
 * query.
 */
const CUSTOM_SQL_CATEGORY: ExpectationCategory = 'Custom SQL';

/**
 * Anomaly (#593) is gated the SAME as Custom SQL — `isSqlQueryable` and the backend's
 * `ANOMALY_CAPABLE_TYPES` are both exactly the SQL-queryable set.
 */
const ANOMALY_CATEGORY: ExpectationCategory = 'Anomaly';

/**
 * The freshness/volume monitor categories (ADR 0012) — offered on any monitor-capable datasource
 * (SQL datasources + Iceberg, `supportsMonitors`).
 */
const MONITOR_CATEGORY_SET = new Set<ExpectationCategory>(MONITOR_CATEGORIES);

const DMF_CATEGORY: ExpectationCategory = 'Snowflake DMF';
const DQX_CATEGORY: ExpectationCategory = 'Databricks DQX';

/** Grouped catalog filtered for a suite's datasource. */
export function expectationsByCategoryFor(
  connectionType: ConnectionType | undefined,
  alwaysIncludeType?: string,
  /** Types this connection's server refuses because of where it points (`refused_expectation_types`). */
  refusedTypes: readonly string[] = [],
): {
  category: ExpectationCategory;
  specs: ExpectationSpec[];
}[] {
  const sqlAllowed = connectionType !== undefined && isSqlQueryable(connectionType);
  const monitorAllowed = connectionType !== undefined && supportsMonitors(connectionType);
  const dmfAllowed = offersDmfEngine(connectionType);
  const dqxAllowed = offersDqxEngine(connectionType);
  const selectedCategory = alwaysIncludeType
    ? EXPECTATION_BY_TYPE[alwaysIncludeType]?.category
    : undefined;
  const allowed = (category: ExpectationCategory): boolean => {
    if (category === selectedCategory) return true;
    if (category === CUSTOM_SQL_CATEGORY || category === ANOMALY_CATEGORY) return sqlAllowed;
    if (category === DMF_CATEGORY) return dmfAllowed;
    if (category === DQX_CATEGORY) return dqxAllowed;
    if (MONITOR_CATEGORY_SET.has(category)) return monitorAllowed;
    return true; // datasource-agnostic category
  };
  // A `dataframeOnly` spec errors on a SQL batch, so drop it per-SPEC rather than per-category —
  // it shares 'Column values' with a dozen types that run everywhere. The type being edited stays
  // visible, or the editor would silently switch the check to something else. Fails CLOSED on an
  // unknown connection type, like every gate above it: the connection load is best-effort, and
  // offering a type the backend then 422s wastes a whole filled-in form.
  const sqlBatch = connectionType === undefined || runsSqlBatch(connectionType);
  const specAllowed = (spec: ExpectationSpec): boolean =>
    spec.type === alwaysIncludeType ||
    ((!spec.dataframeOnly || !sqlBatch) &&
      !refusedTypes.includes(spec.type) &&
      !(
        spec.unsupportedOn &&
        (connectionType === undefined || spec.unsupportedOn.includes(connectionType))
      ));
  return EXPECTATIONS_BY_CATEGORY.filter((g) => allowed(g.category)).map((g) => ({
    category: g.category,
    specs: g.specs.filter(specAllowed),
  }));
}

/** A spec's config fields, adjusted for the suite's datasource (#520). */
export function configFieldsFor(
  spec: ExpectationSpec,
  connectionType: ConnectionType | undefined,
): ConfigField[] {
  if (
    spec.kind !== 'freshness' ||
    connectionType === undefined ||
    !isFileDatasource(connectionType)
  )
    return spec.fields;
  return spec.fields.map((field) =>
    field.name === 'column'
      ? {
          ...field,
          optional: true,
          help: 'Leave blank to measure when the FILE last landed instead — catches a producer that stopped sending files, which a timestamp inside the data cannot.',
        }
      : field,
  );
}

    if lowered.endswith(".parquet"):
        return settings.run_admission_expansion_parquet
    if lowered.endswith((".csv", ".tsv", ".txt")):
        return settings.run_admission_expansion_csv
    return settings.run_admission_expansion_default


def _sample_bytes(target: ResolvedTarget) -> int | None:
    """What a sampled read materialises — far less than the object, so it must not be
    throttled as if it were a full one.
    """
    if target.sampling is None:
        return None
    return target.sampling.rows * get_settings().run_admission_row_bytes


def _flat_file_estimate(connection: Connection, target: ResolvedTarget) -> MemoryEstimate | None:
    from backend.app.datasources.flatfile import file_stat

    if not connection.secret_ref:
        # Nothing to probe the store with. The run fails on the same missing credential
        # moments later, but say so rather than leaving a materialising runner unmetered
        # and silent.
        log.info("run_admission_no_credential", connection_id=str(connection.id))
        return None
    sampled = _sample_bytes(target)
    if sampled is not None:
        # A sample is bounded by the sample whatever the object is, so it needs no probe at all.
        return MemoryEstimate(bytes=sampled, basis="flat_file_sample")
    if target.batch is not None:
        # Resolving a batch target means LISTING the store, which the run path does again
        # moments later — paying for it twice, on every re-queue, is exactly the cost
        # admission exists to avoid. The scan cap is the bound that read is guaranteed to
        # respect, so bound the estimate by the cap rather than by a second listing.
        cap = get_settings().run_max_scan_bytes
        if cap <= 0:
            return MemoryEstimate(bytes=0, basis="flat_file_batch_uncapped", exclusive=True)
        return MemoryEstimate(
            bytes=int(cap * get_settings().run_admission_expansion_default),
            basis="flat_file_batch_cap",
        )
    # A non-batch flat-file target carries the concrete path already, so this is one metadata
    # call and no listing.
    path = target.table
    stat = file_stat(
        conn_type=connection.type,
        config=dict(connection.config),
        path=path,
        secret=get_secret_store().get(connection.secret_ref),
    )
    if stat.size is None:
        # The store would not say. Treat it as unknown, not as zero.
        return MemoryEstimate(bytes=0, basis="flat_file_size_unknown", exclusive=True)
    # Clamped by the scan cap: an over-cap object is refused before it is downloaded, so
    # reserving for the whole 5 GiB would make a run that fails in a second queue behind
    # every other one first.
    cap = get_settings().run_max_scan_bytes
    size = min(stat.size, cap) if cap > 0 else stat.size
    return MemoryEstimate(bytes=int(size * _settings_expansion(path)), basis="flat_file_size")


def _unity_catalog_estimate(
    connection: Connection, target: ResolvedTarget, checks: list[Check]
) -> MemoryEstimate | None:
    """Sized by the runner's own row and width probes, so a small frame reserves what it
    needs instead of the whole frame cap — two metadata queries, not a data read (#2145).
    """
    from backend.app.datasources.unity_catalog import (
        build_unity_catalog_runner,
        frame_lane_required,
    )

    if target.sampling is None:
        types = [c.expectation_type for c in checks if c.kind == "expectation"]
        if not frame_lane_required(types):
            return None
    if not connection.secret_ref or not target.catalog:
        log.info("run_admission_no_credential", connection_id=str(connection.id))
        return None
    settings = get_settings()
    if target.sampling is not None and 0 < settings.run_max_scan_rows < target.sampling.rows:
        # Refused by the sample cap before any probe or read, so it holds nothing.
        return MemoryEstimate(bytes=0, basis="uc_over_cap")
    try:
        runner = build_unity_catalog_runner(
            config=dict(connection.config),
            secret_ref=connection.secret_ref,
            secret_store=get_secret_store(),
            catalog=target.catalog,
            sampling=target.sampling,
        )

