"""Per-dialect SQL for the `aggregate` monitor kind (#1602).

Each aggregate is a Core function element compiled by the connection's own dialect, so the
column is quoted by that dialect and no SQL string is hand-assembled. Only the spellings that
differ between engines are overridden.
"""

from __future__ import annotations

from typing import Any

from sqlalchemy import Float, cast, func, select
from sqlalchemy.exc import CompileError
from sqlalchemy.ext.compiler import compiles
from sqlalchemy.sql import ColumnElement, Select, TableClause
from sqlalchemy.sql.functions import FunctionElement

MEAN = "mean"
MEDIAN = "median"
SUM = "sum"
STDEV = "stdev"
MIN = "min"
MAX = "max"
AGGREGATES = (MEAN, MEDIAN, SUM, STDEV, MIN, MAX)

# Dialects with no exact median aggregate (Trino and Athena offer only `approx_percentile`;
# MySQL has none, MariaDB only a window form MySQL lacks).
_NO_EXACT_MEDIAN = ("mysql", "mariadb", "trino", "awsathena")


class _Median(FunctionElement[Any]):
    type = Float()
    inherit_cache = True


class _StdevSamp(FunctionElement[Any]):
    type = Float()
    inherit_cache = True


def _arg(compiler: Any, element: FunctionElement[Any], **kw: Any) -> str:
    return str(compiler.process(list(element.clauses)[0], **kw))


@compiles(_Median)
def _median_default(element: _Median, compiler: Any, **kw: Any) -> str:
    return f"percentile_cont(0.5) WITHIN GROUP (ORDER BY {_arg(compiler, element, **kw)})"


@compiles(_Median, "snowflake")
@compiles(_Median, "databricks")
@compiles(_Median, "redshift")
def _median_native(element: _Median, compiler: Any, **kw: Any) -> str:
    return f"MEDIAN({_arg(compiler, element, **kw)})"


@compiles(_Median, "mssql")
def _median_mssql(element: _Median, compiler: Any, **kw: Any) -> str:
    # T-SQL's PERCENTILE_CONT is window-only; the statement takes TOP 1 of the identical rows.
    return (
        f"PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY {_arg(compiler, element, **kw)}) OVER ()"
    )


def _median_unsupported(element: _Median, compiler: Any, **kw: Any) -> str:
    raise CompileError(f"no exact median aggregate on the {compiler.dialect.name} dialect")


for _dialect in _NO_EXACT_MEDIAN:
    compiles(_Median, _dialect)(_median_unsupported)


@compiles(_StdevSamp)
def _stdev_default(element: _StdevSamp, compiler: Any, **kw: Any) -> str:
    return f"STDDEV_SAMP({_arg(compiler, element, **kw)})"


@compiles(_StdevSamp, "mssql")
def _stdev_mssql(element: _StdevSamp, compiler: Any, **kw: Any) -> str:
    return f"STDEV({_arg(compiler, element, **kw)})"


class _Widened(FunctionElement[Any]):
    """AVG/SUM whose argument SQL Server widens to FLOAT: over an INT column T-SQL's AVG
    truncates to an integer and its SUM overflows at 2^31."""

    type = Float()
    inherit_cache = True

    def __init__(self, name: str, column: ColumnElement[Any]) -> None:
        self.aggregate_name = name
        super().__init__(column)


@compiles(_Widened)
def _widened_default(element: _Widened, compiler: Any, **kw: Any) -> str:
    return f"{element.aggregate_name}({_arg(compiler, element, **kw)})"


@compiles(_Widened, "mssql")
def _widened_mssql(element: _Widened, compiler: Any, **kw: Any) -> str:
    column = list(element.clauses)[0]
    return f"{element.aggregate_name}({compiler.process(cast(column, Float), **kw)})"


def aggregate_expression(aggregate: str, column: ColumnElement[Any]) -> ColumnElement[Any]:
    if aggregate == MEAN:
        return _Widened("AVG", column)  # type: ignore[return-value]
    if aggregate == SUM:
        return _Widened("SUM", column)  # type: ignore[return-value]
    if aggregate == MEDIAN:
        return _Median(column)  # type: ignore[return-value]
    if aggregate == STDEV:
        return _StdevSamp(column)  # type: ignore[return-value]
    if aggregate == MIN:
        return func.min(column)
    if aggregate == MAX:
        return func.max(column)
    raise ValueError(f"unknown aggregate: {aggregate!r}")


def aggregate_statement(
    target: TableClause, aggregate: str, column: ColumnElement[Any]
) -> Select[Any]:
    statement = select(aggregate_expression(aggregate, column)).select_from(target)
    # The windowed T-SQL median yields one identical row per input row.
    return statement.limit(1) if aggregate == MEDIAN else statement

