  const spec = () => EXPECTATION_BY_TYPE['monitor:aggregate'];
  const aggregateOptions = (type: ConnectionType | undefined): string[] =>
    (configFieldsFor(spec(), type).find((f) => f.name === 'aggregate')?.options ?? []).map(
