s = open(p).read()


def rep(old: str, new: str) -> None:
    global s
    assert old in s, old[:80]
    s = s.replace(old, new, 1)


rep(
    '''def _widened_arg(compiler: Any, element: FunctionElement[Any], **kw: Any) -> str:
    return str(compiler.process(cast(next(iter(element.clauses)), Float), **kw))


@compiles(_Avg)
def _avg(element: _Avg, compiler: Any, **kw: Any) -> str:
    return f"AVG({_arg(compiler, element, **kw)})"
''',
    '''def _double(compiler: Any, element: FunctionElement[Any], **kw: Any) -> str:
    """The argument cast to a double-precision float. Engines keep a DECIMAL aggregate at a
    fixed scale — Trino, Athena and Redshift return AVG at the column's own scale, MySQL and
    MariaDB at scale + 4 (MariaDB's STDDEV_SAMP too), Databricks at scale + 4 — and T-SQL
    truncates AVG of an INT and overflows SUM at 2^31; every one of those is a rounded answer."""
    return str(compiler.process(cast(next(iter(element.clauses)), Double), **kw))


@compiles(_Avg)
def _avg(element: _Avg, compiler: Any, **kw: Any) -> str:
    return f"AVG({_double(compiler, element, **kw)})"
''',
)
rep(
    '''# Over an INT column T-SQL's AVG truncates to an integer and its SUM overflows at 2^31.
@compiles(_Avg, "mssql")
def _avg_mssql(element: _Avg, compiler: Any, **kw: Any) -> str:
    return f"AVG({_widened_arg(compiler, element, **kw)})"


@compiles(_Sum, "mssql")
def _sum_mssql(element: _Sum, compiler: Any, **kw: Any) -> str:
    return f"SUM({_widened_arg(compiler, element, **kw)})"
''',
    '''# A DECIMAL sum is exact at the column's scale everywhere; only T-SQL's INT sum overflows.
@compiles(_Sum, "mssql")
def _sum_mssql(element: _Sum, compiler: Any, **kw: Any) -> str:
    return f"SUM({_double(compiler, element, **kw)})"
''',
)
s = s.replace(
    'return f"percentile_cont(0.5) WITHIN GROUP (ORDER BY {_arg(compiler, element, **kw)})"',
    'return f"percentile_cont(0.5) WITHIN GROUP (ORDER BY {_double(compiler, element, **kw)})"',
)
s = s.replace(
    'return f"MEDIAN({_arg(compiler, element, **kw)})"',
    'return f"MEDIAN({_double(compiler, element, **kw)})"',
)
s = s.replace(
    'return f"PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY {_arg(compiler, element, **kw)}) OVER ()"',
    'return (\n        f"PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY {_double(compiler, element, **kw)}) OVER ()"\n    )',
)
s = s.replace(
    'return f"STDDEV_SAMP({_arg(compiler, element, **kw)})"',
    'return f"STDDEV_SAMP({_double(compiler, element, **kw)})"',
)
s = s.replace(
    'return f"STDEV({_arg(compiler, element, **kw)})"',
    'return f"STDEV({_double(compiler, element, **kw)})"',
)
s = s.replace("from sqlalchemy import Float, cast, func, select", "from sqlalchemy import Double, Float, cast, func, select")
open(p, "w").write(s)

